#include <iostream>
#include <fstream>
#include <string>
#include <map>

using namespace std;

// Function to count the number of occurrences of a word in a text file
void countOccurrences(string line, string word) {
    // Store words in a map to keep track of occurrences
    map<string, int> wordOccurrences;

    // Split line by whitespace and store words in a vector
    string::vector_type words = split(line, " \n");

    // Iterate over each word in vector
    for (string::iterator itr = words.begin(); itr != words.end(); ++itr) {
        // If word matches the given parameter, add 1 to its occurrence count
        if (itr == words.begin() && *itr == word) {
            wordOccurrences[word]++;
        }
    }

    // Return the map containing word-to-occurrences pairs
    return wordOccurrences;
}

