def findCommonElements(arr1, arr2): 
    # Initialize a dictionary to store the common elements 
    common_elements = {} 

    # Iterate through both arrays 
    for i in range(len(arr1)): 
        if arr1[i] in common_elements: 
            # If the element is already present, increment its count 
            common_elements[arr1[i]] += 1 
        else: 
            # Otherwise add the element to the dictionary 
            common_elements[arr1[i]] = 1

    # Iterate through array2 
    for j in range(len(arr2)): 
        # Check if the element is already present in the dictionary 
        if arr2[j] in common_elements: 
            # If yes, increment its count 
            common_elements[arr2[j]] += 1
        # Otherwise add the element to the dictionary 
        else: 
            common_elements[arr2[j]] = 1

    # Return the common elements 
    return common_elements 

